import java.util.*;

class Bitset {
    private final char[] bits;
    private final char[] flippedBits;
    private final int size;
    private int ones;
    private boolean flipped;

    public Bitset(int size) {
        this.size = size;
        bits = new char[size];
        flippedBits = new char[size];
        Arrays.fill(bits, '0');
        Arrays.fill(flippedBits, '1');
    }

    public void fix(int idx) {
        if (current(idx) == '1') {
            return;
        }
        ones++;
        if (flipped) {
            flippedBits[idx] = '1';
            bits[idx] = '0';
        } else {
            bits[idx] = '1';
            flippedBits[idx] = '0';
        }
    }

    public void unfix(int idx) {
        if (current(idx) == '0') {
            return;
        }
        ones--;
        if (flipped) {
            flippedBits[idx] = '0';
            bits[idx] = '1';
        } else {
            bits[idx] = '0';
            flippedBits[idx] = '1';
        }
    }

    public void flip() {
        flipped = !flipped;
        ones = size - ones;
    }

    public boolean all() {
        return ones == size;
    }

    public boolean one() {
        return ones > 0;
    }

    public int count() {
        return ones;
    }

    public String toString() {
        return new String(flipped ? flippedBits : bits);
    }

    private char current(int idx) {
        return flipped ? flippedBits[idx] : bits[idx];
    }
}

class Bitset {
    private final boolean[] raw;
    private final int size;
    private int ones;
    private boolean flipped;

    public Bitset(int size) {
        this.size = size;
        raw = new boolean[size];
    }

    public void fix(int idx) {
        if (!actual(idx)) {
            raw[idx] = !flipped;
            ones++;
        }
    }

    public void unfix(int idx) {
        if (actual(idx)) {
            raw[idx] = flipped;
            ones--;
        }
    }

    public void flip() {
        flipped = !flipped;
        ones = size - ones;
    }

    public boolean all() {
        return ones == size;
    }

    public boolean one() {
        return ones > 0;
    }

    public int count() {
        return ones;
    }

    public String toString() {
        char[] chars = new char[size];
        for (int i = 0; i < size; i++) {
            chars[i] = actual(i) ? '1' : '0';
        }
        return new String(chars);
    }

    private boolean actual(int idx) {
        return raw[idx] ^ flipped;
    }
}

