    private final int size;
    private int ones;
    private boolean flipped;

    public Bitset(int size) {
        this.size = size;
        raw = new BitSet(size);
    }

    public void fix(int idx) {
        if (!actual(idx)) {
            raw.set(idx, !flipped);
            ones++;
        }
    }

    public void unfix(int idx) {
        if (actual(idx)) {
            raw.set(idx, flipped);
            ones--;
        }
    }

    public void flip() {
        flipped = !flipped;
        ones = size - ones;
    }

    public boolean all() {
        return ones == size;
    }

    public boolean one() {
        return ones > 0;
    }

    public int count() {
        return ones;
    }

    public String toString() {
        StringBuilder builder = new StringBuilder(size);
        for (int i = 0; i < size; i++) {
            builder.append(actual(i) ? '1' : '0');
        }
        return builder.toString();
    }

    private boolean actual(int idx) {
        return raw.get(idx) ^ flipped;
    }
}

import java.util.*;

class Bitset {
    private Set<Integer> ones;
    private Set<Integer> zeros;
    private final int size;

    public Bitset(int size) {
        this.size = size;
        ones = new HashSet<>();
        zeros = new HashSet<>();
        for (int i = 0; i < size; i++) {
            zeros.add(i);
        }
    }

    public void fix(int idx) {
        if (zeros.remove(idx)) {
            ones.add(idx);
        }
    }

    public void unfix(int idx) {
        if (ones.remove(idx)) {
            zeros.add(idx);
        }
    }

    public void flip() {
        Set<Integer> temp = ones;
        ones = zeros;
        zeros = temp;
    }

    public boolean all() {
        return ones.size() == size;
    }

    public boolean one() {
        return !ones.isEmpty();
    }

    public int count() {
        return ones.size();
    }

    public String toString() {
        StringBuilder builder = new StringBuilder(size);
        for (int i = 0; i < size; i++) {
            builder.append(ones.contains(i) ? '1' : '0');
        }
        return builder.toString();
    }
}

class Bitset {
    private final int size;
    private final int[] treeOnes;
    private final boolean[] lazyFlip;

    public Bitset(int size) {
        this.size = size;
        treeOnes = new int[size * 4 + 5];
        lazyFlip = new boolean[size * 4 + 5];
    }

    public void fix(int idx) {
        pointSet(1, 0, size - 1, idx, 1);
    }

    public void unfix(int idx) {
        pointSet(1, 0, size - 1, idx, 0);
    }

    public void flip() {
        applyFlip(1, 0, size - 1);
    }

    public boolean all() {
        return treeOnes[1] == size;
    }

    public boolean one() {
        return treeOnes[1] > 0;
    }

    public int count() {
        return treeOnes[1];
    }

    public String toString() {
        char[] chars = new char[size];
        writeString(1, 0, size - 1, chars);
        return new String(chars);
    }

    private void pointSet(int node, int left, int right, int idx, int value) {
        if (left == right) {
            treeOnes[node] = value;
            lazyFlip[node] = false;
            return;
        }
        push(node, left, right);
        int mid = left + (right - left) / 2;
        if (idx <= mid) {
            pointSet(node * 2, left, mid, idx, value);
        } else {
            pointSet(node * 2 + 1, mid + 1, right, idx, value);
        }
        treeOnes[node] = treeOnes[node * 2] + treeOnes[node * 2 + 1];
    }

    private void writeString(int node, int left, int right, char[] chars) {
        if (left == right) {
            chars[left] = treeOnes[node] == 1 ? '1' : '0';
            return;
        }
        push(node, left, right);
        int mid = left + (right - left) / 2;
        writeString(node * 2, left, mid, chars);
        writeString(node * 2 + 1, mid + 1, right, chars);
    }

    private void push(int node, int left, int right) {
        if (!lazyFlip[node] || left == right) {
            return;
        }
        int mid = left + (right - left) / 2;
        applyFlip(node * 2, left, mid);
        applyFlip(node * 2 + 1, mid + 1, right);
        lazyFlip[node] = false;
    }

    private void applyFlip(int node, int left, int right) {
        treeOnes[node] = (right - left + 1) - treeOnes[node];
        lazyFlip[node] = !lazyFlip[node];
    }
}
